CREATE EXTENSION IF NOT EXISTS "uuid-ossp";CREATE TYPE task_status AS ENUM ('To Do', 'In Progress', 'Done');CREATE TYPE task_priority AS ENUM ('Low', 'Medium', 'High', 'Urgent');CREATE TABLE profiles (id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,email TEXT UNIQUE NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;CREATE POLICY "Users can view their own profile." ON profiles FOR SELECT USING (auth.uid() = id);CREATE POLICY "Users can update their own profile." ON profiles FOR UPDATE USING (auth.uid() = id);CREATE POLICY "Users can insert their own profile." ON profiles FOR INSERT WITH CHECK (auth.uid() = id);CREATE TABLE projects (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),owner_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());ALTER TABLE projects ENABLE ROW LEVEL SECURITY;CREATE POLICY "Project owners can view their projects." ON projects FOR SELECT USING (auth.uid() = owner_id);CREATE POLICY "Project owners can insert their projects." ON projects FOR INSERT WITH CHECK (auth.uid() = owner_id);CREATE POLICY "Project owners can update their projects." ON projects FOR UPDATE USING (auth.uid() = owner_id);CREATE POLICY "Project owners can delete their projects." ON projects FOR DELETE USING (auth.uid() = owner_id);CREATE TABLE tasks (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,created_by_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT,status task_status DEFAULT 'To Do' NOT NULL,priority task_priority DEFAULT 'Low' NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());ALTER TABLE tasks ENABLE ROW LEVEL SECURITY;CREATE POLICY "Task owners can view their tasks." ON tasks FOR SELECT USING (EXISTS (SELECT 1 FROM projects WHERE projects.id = tasks.project_id AND projects.owner_id = auth.uid()));CREATE POLICY "Task owners can insert their tasks." ON tasks FOR INSERT WITH CHECK (EXISTS (SELECT 1 FROM projects WHERE projects.id = tasks.project_id AND projects.owner_id = auth.uid()));CREATE POLICY "Task owners can update their tasks." ON tasks FOR UPDATE USING (EXISTS (SELECT 1 FROM projects WHERE projects.id = tasks.project_id AND projects.owner_id = auth.uid()));CREATE POLICY "Task owners can delete their tasks." ON tasks FOR DELETE USING (EXISTS (SELECT 1 FROM projects WHERE projects.id = tasks.project_id AND projects.owner_id = auth.uid()));